create index audit_log_project_idx on public.audit_log (project_id) where project_id is not null;

-- ───────────────────────────── views ─────────────────────────────
-- Hours per work item (non-cost; everyone can read).
create view public.work_item_hours with (security_invoker = true) as
  select work_item_id,
         sum(person_hours)::numeric(10,2) as hours,
         jsonb_object_agg(person_id, person_hours) as hours_by
  from (
    select work_item_id, person_id, sum(hours) as person_hours
    from public.hour_logs group by work_item_id, person_id
  ) s
  group by work_item_id;

-- Cost per work item and per build (owner-only via the underlying hour_log_cost RLS).
create view public.work_item_cost with (security_invoker = true) as
  select l.work_item_id, sum(c.cost)::numeric(12,2) as cost
  from public.hour_logs l join public.hour_log_cost c on c.log_id = l.id
  group by l.work_item_id;

create view public.project_labour with (security_invoker = true) as
  select l.project_id, sum(c.cost)::numeric(12,2) as labour
  from public.hour_logs l join public.hour_log_cost c on c.log_id = l.id
  group by l.project_id;

-- ════════ migration 20261001000200_security.sql ════════
-- Roles & Row Level Security.
--   owner      → everything, including cost tables
--   supervisor → read/write everything except cost tables (which it cannot even read)
--   viewer     → read-only, no cost
--   anon       → nothing. The shop-floor display reads through a server route with the service role.

-- Current user's role, or null if the user has no active profile (uninvited / deactivated).
create or replace function private.current_role() returns public.app_role
language sql stable security definer set search_path = '' as $$
  select p.role from public.profiles p where p.user_id = auth.uid() and p.active
$$;

create or replace function private.is_member() returns boolean
language sql stable security definer set search_path = '' as $$
  select private.current_role() is not null
$$;

create or replace function private.can_write() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(private.current_role() in ('owner', 'supervisor'), false)
$$;

create or replace function private.is_owner() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(private.current_role() = 'owner', false)
$$;

grant usage on schema private to authenticated;
grant execute on function private.current_role(), private.is_member(), private.can_write(), private.is_owner() to authenticated;

-- Small RPC so the app can show "Owner · costs visible" etc. without reading profiles.
create or replace function public.my_role() returns public.app_role
language sql stable security definer set search_path = '' as $$ select private.current_role() $$;
revoke all on function public.my_role() from public, anon;
grant execute on function public.my_role() to authenticated;

-- ───────────── grants: anon gets nothing; authenticated gets table privileges, RLS decides rows ─────────────
revoke all on all tables in schema public from anon;
revoke all on all sequences in schema public from anon;
revoke all on all functions in schema public from anon;
alter default privileges in schema public revoke all on tables from anon;
alter default privileges in schema public revoke all on sequences from anon;
alter default privileges in schema public revoke all on functions from anon;

grant select, insert, update, delete on all tables in schema public to authenticated;
grant usage on all sequences in schema public to authenticated;
-- The audit log is written only by triggers.
revoke insert, update, delete on public.audit_log from authenticated;
-- Hour-log cost rows are written only by SECURITY DEFINER functions (phase 4) or the owner.

-- ───────────── enable RLS everywhere ─────────────
do $$
declare t text;
begin
  for t in select tablename from pg_tables where schemaname = 'public' loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force row level security', t);
  end loop;
end $$;

-- ───────────── standard tables: members read, owner/supervisor write ─────────────
do $$
declare t text;
begin
  foreach t in array array[
    'settings','holidays','station_types','workstations','people',
    'templates','template_stages','template_tasks','template_parts',
    'projects','stages','parts','tasks','baselines','work_items','work_segments','rework_log',
    'attendance','hour_logs'
  ] loop
    execute format('create policy %I on public.%I for select to authenticated using (private.is_member())', t || '_read', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (private.can_write())', t || '_insert', t);
    execute format('create policy %I on public.%I for update to authenticated using (private.can_write()) with check (private.can_write())', t || '_update', t);
    execute format('create policy %I on public.%I for delete to authenticated using (private.can_write())', t || '_delete', t);
  end loop;
end $$;

-- ───────────── owner-only tables (cost + admin) ─────────────
do $$
declare t text;
begin
  foreach t in array array['settings_cost','people_cost','hour_log_cost','invitations','displays'] loop
    execute format('create policy %I on public.%I for all to authenticated using (private.is_owner()) with check (private.is_owner())', t || '_owner', t);
  end loop;
end $$;

-- ───────────── profiles ─────────────
-- Members can see who is who (names in the audit log); only the owner changes roles.
create policy profiles_read on public.profiles for select to authenticated
  using (private.is_member() or user_id = auth.uid());
create policy profiles_owner_write on public.profiles for update to authenticated
  using (private.is_owner()) with check (private.is_owner());
create policy profiles_owner_delete on public.profiles for delete to authenticated
  using (private.is_owner());
-- Inserts happen only in the auth.users trigger (security definer).

-- ───────────── audit log ─────────────
-- Rows that touch cost tables are flagged sensitive and visible to the owner only.
create policy audit_read on public.audit_log for select to authenticated
  using (private.is_member() and (not sensitive or private.is_owner()));

-- ════════ migration 20261001000300_triggers.sql ════════
-- Row bookkeeping, audit log, realtime pings, and invite → profile.

-- ───────────── updated_at + optimistic version ─────────────
-- Every UPDATE bumps `version`. The app updates with `... where id = $1 and version = $2`;
-- zero rows affected means somebody else saved first (fixes §18-3: no silent last-write-wins).
create or replace function private.touch_row() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  new.version := old.version + 1;
  return new;
end $$;

do $$
declare t text;
begin
  for t in
    select c.table_name from information_schema.columns c
    join information_schema.tables tb on tb.table_schema = c.table_schema and tb.table_name = c.table_name
    where c.table_schema = 'public' and c.column_name = 'version' and tb.table_type = 'BASE TABLE'
  loop
    execute format('create trigger touch_row before update on public.%I for each row execute function private.touch_row()', t);
  end loop;
end $$;

-- ───────────── audit ─────────────
-- Tables whose rows are owner-only: their audit entries are flagged sensitive (owner-only too).
create or replace function private.audit_sensitive(tbl text) returns boolean
language sql immutable as $$
  select tbl in ('settings_cost', 'people_cost', 'hour_log_cost', 'displays', 'invitations')
$$;

create or replace function private.audit_row() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  b jsonb; a jsonb; k text;
  bd jsonb := '{}'; ad jsonb := '{}';
  noise text[] := array['updated_at', 'version', 'token_hash'];
  rid text; pid uuid;
begin
  if coalesce(current_setting('app.skip_audit', true), '') = 'on' then
    return null;
  end if;

  if tg_op in ('UPDATE', 'DELETE') then b := to_jsonb(old) - noise; end if;
  if tg_op in ('UPDATE', 'INSERT') then a := to_jsonb(new) - noise; end if;

  if tg_op = 'UPDATE' then
    for k in select jsonb_object_keys(a) loop
      if (b -> k) is distinct from (a -> k) then
        bd := bd || jsonb_build_object(k, b -> k);
        ad := ad || jsonb_build_object(k, a -> k);
      end if;
    end loop;
    if ad = '{}'::jsonb then return null; end if;   -- nothing really changed
    b := bd; a := ad;
  end if;

  rid := coalesce(to_jsonb(coalesce(new, old)) ->> 'id',
                  to_jsonb(coalesce(new, old)) ->> 'key',
                  to_jsonb(coalesce(new, old)) ->> 'user_id',
                  to_jsonb(coalesce(new, old)) ->> 'task_id',
                  to_jsonb(coalesce(new, old)) ->> 'person_id',
                  to_jsonb(coalesce(new, old)) ->> 'log_id',
                  to_jsonb(coalesce(new, old)) ->> 'day');
  pid := case when tg_table_name = 'projects' then (to_jsonb(coalesce(new, old)) ->> 'id')::uuid
              else (to_jsonb(coalesce(new, old)) ->> 'project_id')::uuid end;

  insert into public.audit_log (actor_id, actor_role, action, entity, entity_id, project_id, before, after, sensitive)
  values (auth.uid(), private.current_role(), lower(tg_op), tg_table_name, rid, pid, b, a,
          private.audit_sensitive(tg_table_name));
  return null;
end $$;

do $$
declare t text;
begin
  for t in select tablename from pg_tables where schemaname = 'public' and tablename <> 'audit_log' loop
    execute format('create trigger audit_row after insert or update or delete on public.%I for each row execute function private.audit_row()', t);
  end loop;
end $$;

-- Domain-level actions with a readable label (e.g. 'rebaseline', 'rework'), called by the app.
create or replace function public.audit_action(p_action text, p_entity text, p_entity_id text, p_project_id uuid, p_label text, p_details jsonb default null)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not private.can_write() then raise exception 'Read-only access.' using errcode = '42501'; end if;
  insert into public.audit_log (actor_id, actor_role, action, entity, entity_id, project_id, label, after)
  values (auth.uid(), private.current_role(), p_action, p_entity, p_entity_id, p_project_id, p_label, p_details);
end $$;
revoke all on function public.audit_action(text, text, text, uuid, text, jsonb) from public, anon;
grant execute on function public.audit_action(text, text, text, uuid, text, jsonb) to authenticated;

-- ───────────── realtime "something changed" ping ─────────────
-- Statement-level, so a bulk update sends one ping. The payload carries NO row data —
-- clients refetch through their own permission path (RLS for the console, the display route for TVs).
create or replace function private.notify_change() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  begin
    perform realtime.send(jsonb_build_object('table', tg_table_name, 'op', lower(tg_op)), 'changed', 'kynetik-changes', false);
  exception when others then
    null;  -- realtime must never block a write
  end;
  return null;
end $$;

do $$
declare t text;
begin
  for t in select tablename from pg_tables where schemaname = 'public' and tablename <> 'audit_log' loop
    execute format('create trigger notify_change after insert or update or delete on public.%I for each statement execute function private.notify_change()', t);
  end loop;
end $$;

-- ───────────── invite → profile ─────────────
-- Only invited emails get a profile. Anyone else who somehow gets an auth user has no role and sees nothing.
create or replace function private.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
declare inv public.invitations;
begin
  select * into inv from public.invitations where lower(email) = lower(new.email);
  if found then
    insert into public.profiles (user_id, email, name, role)
    values (new.id, new.email, coalesce(new.raw_user_meta_data ->> 'name', split_part(new.email, '@', 1)), inv.role)
    on conflict (user_id) do nothing;
    update public.invitations set accepted_at = coalesce(accepted_at, now()) where id = inv.id;
  end if;
  return new;
end $$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function private.handle_new_user();

-- An invitation created for someone who already has an auth user takes effect immediately.
create or replace function private.apply_invitation() returns trigger
language plpgsql security definer set search_path = '' as $$
declare u auth.users;
begin
  select * into u from auth.users where lower(email) = lower(new.email);
  if found then
    insert into public.profiles (user_id, email, name, role)
    values (u.id, u.email, split_part(u.email, '@', 1), new.role)
    on conflict (user_id) do update set role = excluded.role, active = true;
    new.accepted_at := coalesce(new.accepted_at, now());
  end if;
  return new;
end $$;

create trigger apply_invitation before insert on public.invitations
  for each row execute function private.apply_invitation();

-- ───────────── always keep one active owner ─────────────
create or replace function private.guard_last_owner() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if not exists (select 1 from public.profiles where role = 'owner' and active) then
    raise exception 'There must always be at least one active Owner.' using errcode = 'P0001';
  end if;
  return null;
end $$;

create constraint trigger guard_last_owner after update or delete on public.profiles
  deferrable initially immediate
  for each row execute function private.guard_last_owner();

-- ════════ migration 20261002000100_build_rpcs.sql ════════
-- Phase 3: multi-row build operations, each in one transaction.
-- All functions are SECURITY INVOKER (the default), so RLS still decides who may write.
-- Business rules are checked in domain/ before these are called; the DB keeps the data consistent.

-- Create a build from a template copy prepared by the app (stages, tasks with their plan, parts).
-- Baseline = plan (spec §7: set automatically on create). One work item per stage × part.
create or replace function public.create_build(p jsonb) returns uuid
language plpgsql set search_path = public as $$
declare
  pid uuid;
  s jsonb;
  t jsonb;
  stage_ids jsonb := '{}';
  sid uuid;
  tid uuid;
begin
  insert into projects (serial, name, template_id, template_label, client, notes, start_date, delivery_date, status, plan_end)
  values (trim(p ->> 'serial'), coalesce(p ->> 'name', ''), nullif(p ->> 'template_id', '')::uuid, coalesce(p ->> 'template_label', ''),
          coalesce(p ->> 'client', ''), coalesce(p ->> 'notes', ''), (p ->> 'start_date')::date, nullif(p ->> 'delivery_date', '')::date,
          'planned', nullif(p ->> 'plan_end', '')::timestamptz)
  returning id into pid;

  for s in select * from jsonb_array_elements(coalesce(p -> 'stages', '[]')) loop
    insert into stages (project_id, name, station_type, station_id, part_hours, sort)
    values (pid, s ->> 'name', s ->> 'station_type', nullif(s ->> 'station_id', '')::uuid, (s ->> 'part_hours')::numeric, (s ->> 'sort')::int)
    returning id into sid;
    stage_ids := stage_ids || jsonb_build_object(s ->> 'key', sid);
  end loop;

  insert into parts (project_id, name, sort)
  select pid, x ->> 'name', (x ->> 'sort')::int from jsonb_array_elements(coalesce(p -> 'parts', '[]')) x;

  for t in select * from jsonb_array_elements(coalesce(p -> 'tasks', '[]')) loop
    insert into tasks (project_id, stage_id, num, name, dur_h, plan_start, plan_end)
    values (pid, (stage_ids ->> (t ->> 'stage_key'))::uuid, (t ->> 'num')::int, t ->> 'name', (t ->> 'dur_h')::numeric,
            (t ->> 'plan_start')::timestamptz, (t ->> 'plan_end')::timestamptz)
    returning id into tid;
    insert into baselines (task_id, project_id, start_at, end_at, set_by)
    values (tid, pid, (t ->> 'plan_start')::timestamptz, (t ->> 'plan_end')::timestamptz, auth.uid());
  end loop;

  insert into work_items (project_id, stage_id, part_id)
  select pid, st.id, pa.id from stages st cross join parts pa where st.project_id = pid and pa.project_id = pid;

  perform audit_action('project.create', 'projects', pid::text, pid, trim(p ->> 'serial'));
  return pid;
end $$;

-- Write a re-flowed plan: task windows (+ optional new duration / pin) and the build's planned finish.
create or replace function public.save_plan(p_project uuid, p_plan_end timestamptz, p_tasks jsonb) returns void
language plpgsql set search_path = public as $$
begin
  update tasks t set
    plan_start = (x ->> 'plan_start')::timestamptz,
    plan_end = (x ->> 'plan_end')::timestamptz
  from jsonb_array_elements(p_tasks) x
  where t.id = (x ->> 'id')::uuid and t.project_id = p_project
    and (t.plan_start is distinct from (x ->> 'plan_start')::timestamptz or t.plan_end is distinct from (x ->> 'plan_end')::timestamptz);
  update projects set plan_end = p_plan_end where id = p_project and plan_end is distinct from p_plan_end;
end $$;

-- Freeze the current plan as the baseline (replaces any old one).
create or replace function public.set_baseline(p_project uuid, p_label text default 'rebaseline') returns void
language plpgsql set search_path = public as $$
declare serial_ text;
begin
  delete from baselines where project_id = p_project;
  insert into baselines (task_id, project_id, start_at, end_at, set_by)
  select id, project_id, plan_start, plan_end, auth.uid() from tasks
  where project_id = p_project and plan_start is not null and plan_end is not null;
  select serial into serial_ from projects where id = p_project;
  perform audit_action(p_label, 'projects', p_project::text, p_project, serial_);
end $$;

-- Send a Done part back for rework: keep the old segment, log the reason, start a new segment.
create or replace function public.rework_item(p_item uuid, p_version int, p_reason text, p_at timestamptz) returns int
language plpgsql set search_path = public as $$
declare w work_items;
begin
  select * into w from work_items where id = p_item for update;
  if not found or w.version <> p_version then
    raise exception 'Someone else changed this — reload and try again.' using errcode = '40001';
  end if;
  if w.status <> 'done' then
    raise exception 'Only a Done part can be sent back for rework.' using errcode = 'P0001';
  end if;
  insert into work_segments (work_item_id, project_id, tech_id, start_at, end_at)
  values (w.id, w.project_id, w.tech_id, coalesce(w.seg_start, w.start_at, p_at), coalesce(w.end_at, p_at));
  insert into rework_log (work_item_id, project_id, at, reason, by_user, by_role)
  values (w.id, w.project_id, p_at, trim(p_reason), auth.uid(), private.current_role());
  update work_items set status = 'doing', rework = rework + 1, seg_start = p_at, end_at = null where id = w.id
  returning version into p_version;
  return p_version;
end $$;

-- Add parts to a build (one work item per stage for each).
create or replace function public.add_parts(p_project uuid, p_names text[]) returns void
language plpgsql set search_path = public as $$
declare base int;
begin
  select coalesce(max(sort), -1) + 1 into base from parts where project_id = p_project;
  with ins as (
    insert into parts (project_id, name, sort)
    select p_project, trim(n), base + ord - 1 from unnest(p_names) with ordinality as u(n, ord)
    returning id
  )
  insert into work_items (project_id, stage_id, part_id)
  select p_project, st.id, ins.id from stages st cross join ins where st.project_id = p_project;
end $$;

-- Add a stage to a build (one work item per part).
create or replace function public.add_stage(p_project uuid, p_name text, p_station_type text, p_station uuid, p_part_hours numeric) returns uuid
language plpgsql set search_path = public as $$
declare sid uuid;
begin
  insert into stages (project_id, name, station_type, station_id, part_hours, sort)
  values (p_project, trim(p_name), p_station_type, p_station, p_part_hours,
          (select coalesce(max(sort), -1) + 1 from stages where project_id = p_project))
  returning id into sid;
  insert into work_items (project_id, stage_id, part_id) select p_project, sid, id from parts where project_id = p_project;
  return sid;
end $$;

-- audit_action is SECURITY DEFINER and checks can_write(); the functions above inherit RLS.
revoke all on function public.create_build(jsonb) from public, anon;
revoke all on function public.save_plan(uuid, timestamptz, jsonb) from public, anon;
revoke all on function public.set_baseline(uuid, text) from public, anon;
revoke all on function public.rework_item(uuid, int, text, timestamptz) from public, anon;
revoke all on function public.add_parts(uuid, text[]) from public, anon;
revoke all on function public.add_stage(uuid, text, text, uuid, numeric) from public, anon;
grant execute on function public.create_build(jsonb), public.save_plan(uuid, timestamptz, jsonb), public.set_baseline(uuid, text),
  public.rework_item(uuid, int, text, timestamptz), public.add_parts(uuid, text[]), public.add_stage(uuid, text, text, uuid, numeric)
  to authenticated, service_role;

-- Segments and rework history are part of the item's record; keep them readable with the item.
create index if not exists work_segments_project_idx on public.work_segments (project_id);
create index if not exists rework_log_project_idx on public.rework_log (project_id);

-- ════════ migration 20261003000100_queue.sql ════════
-- Phase 3.5: departments, employee photos, per-employee task queue, department displays (docs/PLAN.md §7).

-- New settings section.
alter table public.settings drop constraint if exists settings_key_check;
alter table public.settings add constraint settings_key_check
  check (key in ('calendar','booking','health','scoring','labels','brand','floor','timeline','gamification'));

-- Attach the standard row triggers (version bump, audit, realtime ping) to a table created after the first migrations.
create or replace function private.standard_triggers(tbl text) returns void
language plpgsql as $$
begin
  execute format('alter table public.%I enable row level security', tbl);
  execute format('alter table public.%I force row level security', tbl);
  execute format('create trigger touch_row before update on public.%I for each row execute function private.touch_row()', tbl);
  execute format('create trigger audit_row after insert or update or delete on public.%I for each row execute function private.audit_row()', tbl);
  execute format('create trigger notify_change after insert or update or delete on public.%I for each statement execute function private.notify_change()', tbl);
  execute format('revoke all on public.%I from anon', tbl);
  execute format('grant select, insert, update, delete on public.%I to authenticated', tbl);
  execute format('grant all on public.%I to service_role', tbl);
end $$;

-- Members read, owner/supervisor write (same as the standard tables).
create or replace function private.member_policies(tbl text) returns void
language plpgsql as $$
begin
  execute format('create policy %I on public.%I for select to authenticated using (private.is_member())', tbl || '_read', tbl);
  execute format('create policy %I on public.%I for insert to authenticated with check (private.can_write())', tbl || '_insert', tbl);
  execute format('create policy %I on public.%I for update to authenticated using (private.can_write()) with check (private.can_write())', tbl || '_update', tbl);
  execute format('create policy %I on public.%I for delete to authenticated using (private.can_write())', tbl || '_delete', tbl);
end $$;

-- ───────────── departments ─────────────
create table public.departments (
  id         uuid primary key default gen_random_uuid(),
  key        text not null unique check (key ~ '^[a-z][a-z0-9_-]*$'),
  name       text not null check (length(trim(name)) > 0),
  colour     text not null check (colour ~ '^#[0-9A-Fa-f]{6}$'),
  emoji      text not null default '',
  sort       integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version    integer not null default 1
);
select private.standard_triggers('departments');
select private.member_policies('departments');

alter table public.people
  add column department_id uuid references public.departments (id) on delete set null,
  add column photo_path text;
create index people_department_idx on public.people (department_id);

-- ───────────── task queue ─────────────
create type public.duration_unit as enum ('hours', 'days');

create table public.queue_tasks (
  id           uuid primary key default gen_random_uuid(),
  person_id    uuid not null references public.people (id) on delete cascade,
  title        text not null check (length(trim(title)) > 0),
  dur_value    numeric(8,2) not null check (dur_value > 0),
  dur_unit     public.duration_unit not null default 'hours',
  project_id   uuid references public.projects (id) on delete set null,
  stage_id     uuid references public.stages (id) on delete set null,
  work_item_id uuid references public.work_items (id) on delete set null,
  notes        text not null default '',
  colour       text check (colour is null or colour ~ '^#[0-9A-Fa-f]{6}$'),
  fixed_start  timestamptz,
  -- Fractional index (byte order): reordering writes only the moved row.
  position     text collate "C" not null,
  status       public.item_status not null default 'todo',
  actual_start timestamptz,
  actual_end   timestamptz,
  created_by   uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  version      integer not null default 1,
  unique (person_id, position),
  check (actual_end is null or actual_start is null or actual_start <= actual_end)
);
create index queue_tasks_person_idx on public.queue_tasks (person_id, position);
create index queue_tasks_work_item_idx on public.queue_tasks (work_item_id) where work_item_id is not null;
select private.standard_triggers('queue_tasks');
select private.member_policies('queue_tasks');

-- ───────────── displays: one department per link ─────────────
create type public.leaderboard_mode as enum ('side', 'rotate', 'off');
alter table public.displays
  add column department_id uuid references public.departments (id) on delete set null,
  add column leaderboard_mode public.leaderboard_mode not null default 'side',
  add column confetti boolean not null default true;

-- ───────────── employee photos (Supabase Storage) ─────────────
-- Private bucket; members read, owner/supervisor write. Guarded so the migration also runs where Storage isn't installed (tests).
do $$
begin
  if exists (select 1 from information_schema.tables where table_schema = 'storage' and table_name = 'buckets') then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('people-photos', 'people-photos', false, 1048576, array['image/jpeg', 'image/png', 'image/webp'])
    on conflict (id) do nothing;
    execute $p$create policy people_photos_read on storage.objects for select to authenticated
      using (bucket_id = 'people-photos' and private.is_member())$p$;
    execute $p$create policy people_photos_insert on storage.objects for insert to authenticated
      with check (bucket_id = 'people-photos' and private.can_write())$p$;
    execute $p$create policy people_photos_update on storage.objects for update to authenticated
      using (bucket_id = 'people-photos' and private.can_write())$p$;
    execute $p$create policy people_photos_delete on storage.objects for delete to authenticated
      using (bucket_id = 'people-photos' and private.can_write())$p$;
  end if;
end $$;

-- ════════ migration 20261004000100_floor_log.sql ════════
-- Phase 4: floor log (spec §12). Saving a day replaces its hour logs in one transaction and snapshots
-- each log's hour rate into the owner-only hour_log_cost (§13). Runs as SECURITY DEFINER so a Supervisor
-- can log hours without ever reading a rate; the caller must be Owner or Supervisor.

-- Working hours in a day from the calendar settings (D2: shift minus the break inside it).
create or replace function private.day_hours() returns numeric
language sql stable security definer set search_path = '' as $$
  with c as (select coalesce((select value from public.settings where key = 'calendar'), '{}'::jsonb) v),
  m as (
    select
      extract(epoch from coalesce(v ->> 'shiftStart', '09:00')::time) / 60 s,
      extract(epoch from coalesce(v ->> 'shiftEnd', '18:00')::time) / 60 e,
      extract(epoch from coalesce(v ->> 'breakStart', '13:00')::time) / 60 bs,
      coalesce((v ->> 'breakMins')::numeric, 60) bm
    from c
  )
  select (e - s - greatest(0, least(e, bs + bm) - greatest(s, bs))) / 60 from m
$$;

-- Hour rate for a person now: loaded monthly ÷ working days ÷ day hours; admin class never enters build cost.
create or replace function private.hour_rate(p_person uuid) returns numeric
language sql stable security definer set search_path = '' as $$
  select case when p.cost_class = 'admin' then 0 else
    coalesce(pc.base_salary, 0)
      * (1 + coalesce(pc.loading_pct, sc.default_loading_pct, 25) / 100)
      / nullif(coalesce(sc.working_days_per_month, 26), 0)
      / nullif(private.day_hours(), 0)
  end
  from public.people p
  left join public.people_cost pc on pc.person_id = p.id
  left join public.settings_cost sc on true
  where p.id = p_person
$$;

-- Save one day: attendance [{person_id, present}] and logs [{person_id, work_item_id, hours}].
-- Logs that existed before for the same person and part-step keep their original rate (snapshot at logging time).
create or replace function public.commit_day(p_day date, p_attendance jsonb, p_logs jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare
  cap numeric := private.day_hours();
  over record;
begin
  if not private.can_write() then
    raise exception 'Read-only access. Ask the Owner for Supervisor access to make changes.' using errcode = '42501';
  end if;

  insert into public.attendance (day, person_id, present)
  select distinct on ((a ->> 'person_id')::uuid) p_day, (a ->> 'person_id')::uuid, (a ->> 'present')::boolean
  from jsonb_array_elements(coalesce(p_attendance, '[]')) a
  on conflict (day, person_id) do update set present = excluded.present where public.attendance.present is distinct from excluded.present;

  -- A working day holds `cap` hours per person (§12, §15).
  select p.name, sum((l ->> 'hours')::numeric) h into over
  from jsonb_array_elements(coalesce(p_logs, '[]')) l join public.people p on p.id = (l ->> 'person_id')::uuid
  group by p.name having sum((l ->> 'hours')::numeric) > cap limit 1;
  if found then
    raise exception '% already has %h on % — a working day holds %h.', over.name, trim_scale(over.h), to_char(p_day, 'FMDD Mon'), trim_scale(cap) using errcode = 'P0001';
  end if;

  drop table if exists _old_rates;
  create temp table _old_rates on commit drop as
    select l.person_id, l.work_item_id, max(c.rate) rate
    from public.hour_logs l join public.hour_log_cost c on c.log_id = l.id
    where l.day = p_day group by l.person_id, l.work_item_id;

  delete from public.hour_logs where day = p_day;  -- hour_log_cost cascades

  with ins as (
    insert into public.hour_logs (day, person_id, work_item_id, project_id, hours, created_by)
    select p_day, (l ->> 'person_id')::uuid, w.id, w.project_id, (l ->> 'hours')::numeric, auth.uid()
    from jsonb_array_elements(coalesce(p_logs, '[]')) l
    join public.work_items w on w.id = (l ->> 'work_item_id')::uuid
    where (l ->> 'hours')::numeric > 0
    returning id, person_id, work_item_id, hours
  )
  insert into public.hour_log_cost (log_id, rate, cost)
  select ins.id, r.rate, round(ins.hours * r.rate, 2)
  from ins
  cross join lateral (
    select coalesce((select o.rate from _old_rates o where o.person_id = ins.person_id and o.work_item_id = ins.work_item_id), private.hour_rate(ins.person_id), 0) rate
  ) r;
end $$;

revoke all on function public.commit_day(date, jsonb, jsonb) from public, anon;
grant execute on function public.commit_day(date, jsonb, jsonb) to authenticated, service_role;
revoke all on function private.day_hours(), private.hour_rate(uuid) from public, anon, authenticated;

-- Labour per day for the owner (Floor log tiles / This week). security_invoker: owner-only via hour_log_cost RLS.
create or replace view public.day_labour with (security_invoker = true) as
  select l.day, l.person_id, sum(c.cost)::numeric(12,2) as cost
  from public.hour_logs l join public.hour_log_cost c on c.log_id = l.id
  group by l.day, l.person_id;
grant select on public.day_labour to authenticated;
revoke all on public.day_labour from anon;

-- ════════ migration 20261007000100_plan_and_notices.sql ════════
-- v1 (docs/ROADMAP.md): week planner priority flag and department TV notices.

-- ───────────── week planner: urgent flag on a plan task ─────────────
alter table public.queue_tasks
  add column priority text not null default 'normal' check (priority in ('normal', 'urgent'));

-- ───────────── TV notices ─────────────
-- Shown on the department TV, rotating in the header. Either a message, or a daily countdown
-- ("Quality check in 25 min") when daily_at is set. department_id null = every department.
create table public.notices (
  id            uuid primary key default gen_random_uuid(),
  department_id uuid references public.departments (id) on delete cascade,
  icon          text not null default '📢',
  title         text not null check (length(trim(title)) > 0),
  detail        text not null default '',
  daily_at      time,
  starts_on     date,
  ends_on       date,
  active        boolean not null default true,
  sort          integer not null default 0,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  version       integer not null default 1,
  check (ends_on is null or starts_on is null or starts_on <= ends_on)
);
create index notices_department_idx on public.notices (department_id);

select private.standard_triggers('notices');
select private.member_policies('notices');

-- ════════ migration 20261008000100_duration_minutes.sql ════════
-- v2: task durations in hours and minutes (docs/ux/DECISIONS.md 2026-10-07). Two decimals of an hour
-- could not hold a minute exactly (1 min = 0.0167 h); four decimals round-trip every whole minute.
alter table public.queue_tasks alter column dur_value type numeric(10,4);

-- ════════ migration 20261008000200_save_as_template.sql ════════
-- v2: "Save as template" on a build (docs/ux/DECISIONS.md 2026-10-07). The app prepares the copy
-- (stages, tasks with hours, parts; never dates, people or costs) and this writes it in one transaction.
-- SECURITY INVOKER (the default), so RLS on the template tables decides who may write.
create or replace function public.create_template(p jsonb) returns uuid
language plpgsql set search_path = public as $$
declare
  tid uuid;
  sid uuid;
  s jsonb;
  t jsonb;
  i int := 0;
  j int;
begin
  insert into templates (key, label) values (p ->> 'key', trim(p ->> 'label')) returning id into tid;
  for s in select * from jsonb_array_elements(coalesce(p -> 'stages', '[]')) loop
    i := i + 1;
    insert into template_stages (template_id, name, station_type, part_hours, sort)
    values (tid, s ->> 'name', s ->> 'station_type', (s ->> 'part_hours')::numeric, i)
    returning id into sid;
    j := 0;
    for t in select * from jsonb_array_elements(coalesce(s -> 'tasks', '[]')) loop
      j := j + 1;
      insert into template_tasks (template_id, template_stage_id, name, dur_h, sort)
      values (tid, sid, t ->> 'name', (t ->> 'dur_h')::numeric, j);
    end loop;
  end loop;
  insert into template_parts (template_id, name, sort)
  select tid, x.name, x.ord::int from jsonb_array_elements_text(coalesce(p -> 'parts', '[]')) with ordinality as x(name, ord);
  perform audit_action('template.create', 'templates', tid::text, nullif(p ->> 'from_project', '')::uuid, trim(p ->> 'label'));
  return tid;
end $$;

revoke all on function public.create_template(jsonb) from public, anon;
grant execute on function public.create_template(jsonb) to authenticated, service_role;

-- ════════ migration 20261008000300_crew_profile.sql ════════
-- v2 Crew portal (docs/ux/DECISIONS.md 2026-10-07): Crew and Technicians in one place, work-type tags
-- Full time / Project based (Owner's choice), contract dates and the builds a project-based person is on,
-- plus contact and skills. No pay here: pay stays in the owner-only people_cost table.
alter table public.people
  add column employment   text not null default 'full_time' check (employment in ('full_time', 'project_based')),
  add column contract_from date,
  add column contract_to   date,
  add column phone         text not null default '',
  add column skills        text not null default '',
  add column notes         text not null default '',
  add column project_ids   uuid[] not null default '{}',
  add constraint people_contract_order check (contract_to is null or contract_from is null or contract_to >= contract_from);

-- ════════ migration 20261012000100_company_email_only.sql ════════
-- Company addresses only (Owner, 2026-10-12, docs/ux/DECISIONS.md): access is limited to
-- @kynetikkoncepts.com emails. Enforced here so no path around the app (Microsoft, email link,
-- a stray auth user, an old profile) gets in:
--   · an invitation for any other address is refused;
--   · a new auth user with any other address gets no profile;
--   · an existing profile with any other address has no role, so RLS shows it nothing.
-- Rows are kept, not deleted, so history and the audit log stay intact.

create or replace function private.company_email(e text) returns boolean
language sql immutable set search_path = '' as $$
  select coalesce(lower(split_part(trim(e), '@', 2)) = 'kynetikkoncepts.com', false)
$$;
grant execute on function private.company_email(text) to authenticated;

create or replace function private.current_role() returns public.app_role
language sql stable security definer set search_path = '' as $$
  select p.role from public.profiles p where p.user_id = auth.uid() and p.active and private.company_email(p.email)
$$;

-- Runs before apply_invitation (triggers fire in name order).
create or replace function private.check_invitation_email() returns trigger
language plpgsql set search_path = '' as $$
begin
  if not private.company_email(new.email) then
    raise exception 'Only @kynetikkoncepts.com addresses can be invited.' using errcode = 'P0001';
  end if;
  return new;
end $$;

create trigger a_check_invitation_email before insert or update of email on public.invitations
  for each row execute function private.check_invitation_email();

create or replace function private.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
declare inv public.invitations;
begin
  if not private.company_email(new.email) then return new; end if;
  select * into inv from public.invitations where lower(email) = lower(new.email);
  if found then
    insert into public.profiles (user_id, email, name, role)
    values (new.id, new.email, coalesce(new.raw_user_meta_data ->> 'name', split_part(new.email, '@', 1)), inv.role)
    on conflict (user_id) do nothing;
    update public.invitations set accepted_at = coalesce(accepted_at, now()) where id = inv.id;
  end if;
  return new;
end $$;

-- The Owner who keeps the app running must be one who can still sign in.
create or replace function private.guard_last_owner() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if not exists (select 1 from public.profiles where role = 'owner' and active and private.company_email(email)) then
    raise exception 'There must always be at least one active Owner.' using errcode = 'P0001';
  end if;
  return null;
end $$;

-- ════════ migration 20261012000200_panel_parts.sql ════════
-- Amends round 2026-10-12 (AMENDS_NEXT_ROUND.md AM-01, AM-04, AM-11; answers in docs/ux/DECISIONS.md):
--   · parts get a serial (unique across the whole system and never reused), a parent (one level only:
--     a part with sub-parts is a folder), description, material and finish;
--   · projects made on the new workflow are "gated" (old projects keep working as they do now);
--   · a Modelling department and station type;
--   · the 10-stage "Exterior panels" template replaces the old ones for new projects (old ones archived).

-- ───────────── Modelling department ─────────────
insert into public.station_types (key, label, colour, sort)
values ('modelling', 'Modelling', '#9C8FC4', -1)
on conflict (key) do nothing;

insert into public.departments (key, name, colour, emoji, sort)
values ('modelling', 'Modelling', '#9C8FC4', '📐', -1)
on conflict (key) do nothing;

-- ───────────── parts: serial, sub-parts, material and finish ─────────────
alter table public.parts
  add column serial        text check (serial ~ '^\d{2}-\d{2}-\d{3}(-[A-Z])?(-[1-9]\d*)?$'),
  add column parent_id     uuid references public.parts (id) on delete cascade,
  add column description   text not null default '',
  add column material      text check (material in ('Carbon fiber', 'Twill', 'Forged carbon', 'Fiberglass')),
  add column finish_colour text,
  add column finish_sheen  text check (finish_sheen in ('Matte', 'Satin', 'Gloss')),
  add column unit_no       integer check (unit_no >= 1),
  add check (parent_id is null or parent_id <> id);

create unique index parts_serial_key on public.parts (lower(serial)) where serial is not null;
create index parts_parent_idx on public.parts (parent_id) where parent_id is not null;

-- Two units of one part share a name, so names stay unique only for old (serial-less) parts.
drop index public.parts_project_name_key;
create unique index parts_project_name_key on public.parts (project_id, lower(name)) where serial is null;

-- One level only, same project.
create or replace function private.check_part_parent() returns trigger
language plpgsql security definer set search_path = '' as $$
declare par public.parts;
begin
  if new.parent_id is null then return new; end if;
  select * into par from public.parts where id = new.parent_id;
  if par.project_id <> new.project_id then
    raise exception 'A sub-part belongs to the same project as its parent.' using errcode = 'P0001';
  end if;
  if par.parent_id is not null then
    raise exception 'Only one level of sub-parts: % is already a sub-part.', coalesce(par.serial, par.name) using errcode = 'P0001';
  end if;
  if exists (select 1 from public.parts c where c.parent_id = new.id) then
    raise exception 'A part with sub-parts can''t become a sub-part.' using errcode = 'P0001';
  end if;
  return new;
end $$;

create trigger check_part_parent before insert or update of parent_id, project_id on public.parts
  for each row execute function private.check_part_parent();

-- Serials are never reused: every serial ever given is kept here, even after its part is deleted.
create table public.serial_registry (
  serial     text primary key,
  created_at timestamptz not null default now()
);
alter table public.serial_registry enable row level security;
alter table public.serial_registry force row level security;
revoke all on public.serial_registry from anon;
grant select on public.serial_registry to authenticated;
grant all on public.serial_registry to service_role;
create policy serial_registry_read on public.serial_registry for select to authenticated using (private.is_member());

create or replace function private.register_serial() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.serial is null or (tg_op = 'UPDATE' and lower(new.serial) = lower(coalesce(old.serial, ''))) then return new; end if;
  insert into public.serial_registry (serial) values (lower(new.serial)) on conflict do nothing;
  if not found then
    raise exception 'Serial % has already been used. Serials are never reused.', new.serial using errcode = 'P0001';
  end if;
  return new;
end $$;

create trigger register_serial before insert or update of serial on public.parts
  for each row execute function private.register_serial();

-- ───────────── projects on the new workflow ─────────────
alter table public.projects add column gated boolean not null default false;

-- ───────────── the 10-stage Exterior panels template ─────────────
-- On a fresh database the station types come with the seed (after migrations), so the seed adds the
-- template there (supabase/seed/generate.ts); here it is added for a database that already has them.
do $$
declare tid uuid;
begin
  if (select count(*) from public.station_types where key in ('modification', 'fitment', 'paint')) < 3 then
    return;
  end if;
  insert into public.templates (key, label) values ('exteriorPanels', 'Exterior panels')
  on conflict (key) do nothing returning id into tid;
  if tid is not null then
    insert into public.template_stages (template_id, name, station_type, part_hours, sort)
    select tid, s.name, s.station_type, 0, s.sort
    from (values
      ('Modelling', 'modelling', 0),
      ('3D printing', 'modification', 1),
      ('Prototyping', 'modification', 2),
      ('Pre-mold production', 'modification', 3),
      ('Mold production', 'modification', 4),
      ('Carbon fibre component production', 'modification', 5),
      ('Fitment', 'fitment', 6),
      ('Paint preparation & painting', 'paint', 7),
      ('Sanding & polishing', 'paint', 8),
      ('Assembly', 'fitment', 9)
    ) as s (name, station_type, sort);
  end if;
  update public.templates set archived = true where key <> 'exteriorPanels' and not archived;
end $$;

-- ───────────── create a project on the new workflow ─────────────
-- p: { serial, name, client, notes, start_date, delivery_date,
--      parts: [{ key, parent_key, serial, name, description, material, finish_colour, finish_sheen, unit_no, sort }] }
-- Stages come from the Exterior panels template (first workstation of each type). Work items are made for
-- trackable parts only: a part with sub-parts is a folder. No tasks: admins set every time (AM-08).
-- SECURITY INVOKER, so RLS decides who may write.
create or replace function public.create_panel_project(p jsonb) returns uuid
language plpgsql set search_path = public as $$
declare
  pid uuid;
  tid uuid;
  x jsonb;
  keys jsonb := '{}';
  new_id uuid;
begin
  select id into tid from templates where key = 'exteriorPanels';
  if tid is null then raise exception 'The Exterior panels template is missing.' using errcode = 'P0001'; end if;

  insert into projects (serial, name, template_id, template_label, client, notes, start_date, delivery_date, status, gated)
  values (trim(p ->> 'serial'), coalesce(p ->> 'name', ''), tid, 'Exterior panels', coalesce(p ->> 'client', ''),
          coalesce(p ->> 'notes', ''), (p ->> 'start_date')::date, nullif(p ->> 'delivery_date', '')::date, 'planned', true)
  returning id into pid;

  insert into stages (project_id, name, station_type, station_id, part_hours, sort)
  select pid, ts.name, ts.station_type,
         (select w.id from workstations w where w.station_type = ts.station_type order by w.sort, w.name limit 1), 0, ts.sort
  from template_stages ts where ts.template_id = tid;

  -- Parents first, so sub-parts can point at them.
  for x in select * from jsonb_array_elements(coalesce(p -> 'parts', '[]')) order by (value ->> 'parent_key') is not null loop
    insert into parts (project_id, parent_id, serial, name, description, material, finish_colour, finish_sheen, unit_no, sort)
    values (pid, nullif(keys ->> (x ->> 'parent_key'), '')::uuid, x ->> 'serial', trim(x ->> 'name'), coalesce(x ->> 'description', ''),
            x ->> 'material', x ->> 'finish_colour', x ->> 'finish_sheen', nullif(x ->> 'unit_no', '')::int, (x ->> 'sort')::int)
    returning id into new_id;
    keys := keys || jsonb_build_object(x ->> 'key', new_id);
  end loop;

  insert into work_items (project_id, stage_id, part_id)
  select pid, st.id, pa.id from stages st cross join parts pa
  where st.project_id = pid and pa.project_id = pid
    and not exists (select 1 from parts c where c.parent_id = pa.id);

  perform audit_action('project.create', 'projects', pid::text, pid, trim(p ->> 'serial'));
  return pid;
end $$;

-- Add parts (and their sub-parts) to a project on the new workflow; same payload shape as above, plus
-- parent_id for a sub-part added under an existing part. A part that gains its first sub-part becomes a
-- folder: its own work items go, as long as none of them has started.
create or replace function public.add_panel_parts(p_project uuid, p_parts jsonb) returns void
language plpgsql set search_path = public as $$
declare
  x jsonb;
  keys jsonb := '{}';
  new_id uuid;
  par uuid;
begin
  for x in select * from jsonb_array_elements(coalesce(p_parts, '[]')) order by (value ->> 'parent_key') is not null loop
    par := coalesce(nullif(x ->> 'parent_id', '')::uuid, nullif(keys ->> (x ->> 'parent_key'), '')::uuid);
    if par is not null and exists (select 1 from work_items w where w.part_id = par and w.status <> 'todo') then
      raise exception 'That part has work started on it, so it can''t be split into sub-parts.' using errcode = 'P0001';
    end if;
    insert into parts (project_id, parent_id, serial, name, description, material, finish_colour, finish_sheen, unit_no, sort)
    values (p_project, par, x ->> 'serial', trim(x ->> 'name'), coalesce(x ->> 'description', ''),
            x ->> 'material', x ->> 'finish_colour', x ->> 'finish_sheen', nullif(x ->> 'unit_no', '')::int,
            coalesce((x ->> 'sort')::int, (select coalesce(max(sort), -1) + 1 from parts where project_id = p_project)))
    returning id into new_id;
    keys := keys || jsonb_build_object(x ->> 'key', new_id);
    if par is not null then delete from work_items w where w.part_id = par; end if;
  end loop;

  insert into work_items (project_id, stage_id, part_id)
  select p_project, st.id, pa.id from stages st cross join parts pa
  where st.project_id = p_project and pa.project_id = p_project
    and not exists (select 1 from parts c where c.parent_id = pa.id)
    and not exists (select 1 from work_items w where w.stage_id = st.id and w.part_id = pa.id);
end $$;

-- ════════ migration 20261012000300_qc_gate.sql ════════
-- Amends round 2026-10-12, part 2 (AMENDS_NEXT_ROUND AM-06, AM-07, AM-08; answers in docs/ux/DECISIONS.md):
--   · admin QC gate on projects made on the new workflow (projects.gated): a finished step is submitted for
--     QC and only an approval marks it Done; a rejection sends it back to the same technician as rework;
--   · a step can't start before every earlier stage of its part is approved;
--   · mold components: after pre-mold is approved an admin sets how many, and each becomes its own
--     tracked step in Mold production;
--   · rework time is kept apart from the first attempt (work_segments.attempt).
-- Waiting for QC is not a new status: the step stays In Progress (its clock keeps running, so QC time
-- counts inside the allocated time, AM-07) with qc_since set. Old projects are untouched.

-- ───────────── which stage is which (new workflow) ─────────────
alter table public.template_stages add column step text;
alter table public.stages add column step text;
update public.template_stages ts set step = s.step
from (values ('Modelling', 'modelling'), ('3D printing', 'printing'), ('Prototyping', 'prototyping'),
             ('Pre-mold production', 'premold'), ('Mold production', 'mold'), ('Carbon fibre component production', 'carbon'),
             ('Fitment', 'fitment'), ('Paint preparation & painting', 'paint'), ('Sanding & polishing', 'sanding'), ('Assembly', 'assembly')) as s (name, step)
where ts.name = s.name and ts.template_id = (select id from public.templates where key = 'exteriorPanels');
update public.stages st set step = ts.step
from public.projects p, public.template_stages ts
where p.id = st.project_id and p.gated and ts.template_id = p.template_id and ts.name = st.name;

-- ───────────── work items: QC, attempts, mold components ─────────────
alter table public.work_items
  add column qc_since      timestamptz,
  add column qc_by         uuid references auth.users (id) on delete set null,
  add column attempt       integer not null default 1 check (attempt >= 1),
  add column component_no  integer check (component_no >= 1),
  add column component_total integer check (component_total >= 1),
  add check ((component_no is null) = (component_total is null) and (component_no is null or component_no <= component_total));
alter table public.work_items drop constraint work_items_stage_id_part_id_key;
create unique index work_items_stage_part_key on public.work_items (stage_id, part_id, coalesce(component_no, 0));

-- Allocated time to the minute, like the task queue (AM-08: set by admins on the queue).
alter table public.work_items alter column plan_h type numeric(10,4);

alter table public.work_segments add column attempt integer not null default 1 check (attempt >= 1);

-- ───────────── QC history (who submitted, who decided, why it failed) ─────────────
create table public.qc_reviews (
  id           uuid primary key default gen_random_uuid(),
  project_id   uuid not null references public.projects (id) on delete cascade,
  work_item_id uuid not null references public.work_items (id) on delete cascade,
  tech_id      uuid references public.people (id) on delete set null,
  attempt      integer not null default 1,
  submitted_at timestamptz not null default now(),
  submitted_by uuid references auth.users (id) on delete set null,
  decided_at   timestamptz,
  decided_by   uuid references auth.users (id) on delete set null,
  result       text check (result in ('approved', 'rejected')),
  reason       text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version    integer not null default 1,
  check ((result is null) = (decided_at is null)),
  check (result is distinct from 'rejected' or length(trim(reason)) > 0)
);
create index qc_reviews_item_idx on public.qc_reviews (work_item_id);
create index qc_reviews_open_idx on public.qc_reviews (project_id) where result is null;
select private.standard_triggers('qc_reviews');
select private.member_policies('qc_reviews');

-- ───────────── the gate ─────────────
create or replace function private.qc_gate() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  gated boolean;
  st public.stages;
  waiting text;
begin
  select p.gated into gated from public.projects p where p.id = new.project_id;
  if not coalesce(gated, false) then return new; end if;
  select * into st from public.stages where id = new.stage_id;

  -- No start before every earlier stage of this part is approved.
  if new.status in ('doing', 'done') and old.status in ('todo', 'blocked') then
    select string_agg(distinct s2.name, ', ') into waiting
    from public.work_items w join public.stages s2 on s2.id = w.stage_id
    where w.part_id = new.part_id and s2.project_id = new.project_id and s2.sort < st.sort and w.status <> 'done';
    if waiting is not null then
      raise exception 'This part is still in %. A stage starts once the stage before it has passed QC.', waiting using errcode = 'P0001';
    end if;
    if st.step = 'mold' and new.component_total is null then
      raise exception 'Set how many mold components this part needs before Mold production starts.' using errcode = 'P0001';
    end if;
  end if;

  -- Done only through an approval.
  if new.status = 'done' and old.status <> 'done' and current_setting('app.qc_approve', true) is distinct from 'on' then
    raise exception 'On this project a step is marked Done by approving it in QC. Submit it for QC instead.' using errcode = 'P0001';
  end if;
  -- Leaving In Progress some other way (blocked, reset) withdraws a pending QC request.
  if new.status <> 'doing' and old.qc_since is not null then
    new.qc_since := null; new.qc_by := null;
    delete from public.qc_reviews where work_item_id = new.id and result is null;
  end if;
  return new;
end $$;

create trigger qc_gate before update of status on public.work_items
  for each row execute function private.qc_gate();

-- ───────────── submit, approve, reject ─────────────
-- SECURITY INVOKER: RLS decides who may write (Owner and Supervisors).
create or replace function public.submit_qc(p_item uuid) returns void
language plpgsql set search_path = public as $$
declare w work_items;
begin
  select * into w from work_items where id = p_item for update;
  if not found then raise exception 'That step no longer exists. Reload the page.' using errcode = 'P0001'; end if;
  if not (select gated from projects where id = w.project_id) then
    raise exception 'This project has no QC step; mark it Done.' using errcode = 'P0001';
  end if;
  if w.status <> 'doing' then raise exception 'Only a step In Progress can be submitted for QC.' using errcode = 'P0001'; end if;
  if w.tech_id is null then raise exception 'Assign a technician before submitting for QC.' using errcode = 'P0001'; end if;
  if w.qc_since is not null then raise exception 'This step is already waiting for QC.' using errcode = 'P0001'; end if;
  update work_items set qc_since = now(), qc_by = auth.uid() where id = w.id;
  insert into qc_reviews (project_id, work_item_id, tech_id, attempt, submitted_by)
  values (w.project_id, w.id, w.tech_id, w.attempt, auth.uid());
end $$;

create or replace function public.decide_qc(p_item uuid, p_approve boolean, p_reason text) returns void
language plpgsql set search_path = public as $$
declare w work_items;
begin
  select * into w from work_items where id = p_item for update;
  if not found then raise exception 'That step no longer exists. Reload the page.' using errcode = 'P0001'; end if;
  if w.qc_since is null then raise exception 'This step is not waiting for QC.' using errcode = 'P0001'; end if;
  if p_approve then
    update qc_reviews set decided_at = now(), decided_by = auth.uid(), result = 'approved'
    where work_item_id = w.id and result is null;
    perform set_config('app.qc_approve', 'on', true);
    update work_items set status = 'done', end_at = now() where id = w.id;
    perform set_config('app.qc_approve', 'off', true);
    update queue_tasks set status = 'done', actual_end = now() where work_item_id = w.id and status <> 'done';
  else
    if length(trim(coalesce(p_reason, ''))) = 0 then
      raise exception 'Say what failed — it is the only way the rework history is useful.' using errcode = 'P0001';
    end if;
    -- The attempt so far (its QC wait included) closes; the same technician carries on as rework.
    insert into work_segments (work_item_id, project_id, tech_id, start_at, end_at, attempt)
    values (w.id, w.project_id, w.tech_id, coalesce(w.seg_start, w.start_at, now()), now(), w.attempt);
    insert into rework_log (work_item_id, project_id, at, reason, by_user, by_role)
    values (w.id, w.project_id, now(), 'QC: ' || trim(p_reason), auth.uid(), private.current_role());
    update work_items set rework = rework + 1, attempt = attempt + 1, seg_start = now(), qc_since = null, qc_by = null where id = w.id;
    update qc_reviews set decided_at = now(), decided_by = auth.uid(), result = 'rejected', reason = trim(p_reason)
    where work_item_id = w.id and result is null;
  end if;
end $$;

-- Rework of an approved step (found later) counts as another attempt too.
create or replace function public.rework_item(p_item uuid, p_version int, p_reason text, p_at timestamptz) returns int
language plpgsql set search_path = public as $$
declare w work_items;
begin
  select * into w from work_items where id = p_item for update;
  if not found or w.version <> p_version then
    raise exception 'Someone else changed this — reload and try again.' using errcode = '40001';
  end if;
  if w.status <> 'done' then
    raise exception 'Only a Done part can be sent back for rework.' using errcode = 'P0001';
  end if;
  insert into work_segments (work_item_id, project_id, tech_id, start_at, end_at, attempt)
  values (w.id, w.project_id, w.tech_id, coalesce(w.seg_start, w.start_at, p_at), coalesce(w.end_at, p_at), w.attempt);
  insert into rework_log (work_item_id, project_id, at, reason, by_user, by_role)
  values (w.id, w.project_id, p_at, trim(p_reason), auth.uid(), private.current_role());
  update work_items set status = 'doing', rework = rework + 1, attempt = attempt + 1, seg_start = p_at, end_at = null where id = w.id
  returning version into p_version;
  return p_version;
end $$;

-- ───────────── mold components (AM-06) ─────────────
-- After pre-mold is approved: n components replace the part's single Mold step (or change the count while
-- none has started). Each is a tracked step with its own technician and status.
create or replace function public.set_mold_components(p_part uuid, p_n int) returns void
language plpgsql set search_path = public as $$
declare
  pa parts;
  mold stages;
  premold_done boolean;
begin
  if p_n is null or p_n < 1 or p_n > 50 then raise exception 'Enter how many mold components: a whole number from 1 to 50.' using errcode = 'P0001'; end if;
  select * into pa from parts where id = p_part;
  if not found then raise exception 'That part no longer exists. Reload the page.' using errcode = 'P0001'; end if;
  select * into mold from stages where project_id = pa.project_id and step = 'mold';
  if not found then raise exception 'This project has no Mold production stage.' using errcode = 'P0001'; end if;
  select bool_and(w.status = 'done') into premold_done
  from work_items w join stages s on s.id = w.stage_id where w.part_id = p_part and s.step = 'premold';
  if not coalesce(premold_done, false) then
    raise exception 'Pre-mold production has to pass QC before the mold components are set.' using errcode = 'P0001';
  end if;
  if exists (select 1 from work_items where part_id = p_part and stage_id = mold.id and status <> 'todo') then
    raise exception 'Work has started on this part''s mold, so the number of components can''t change.' using errcode = 'P0001';
  end if;
  delete from work_items where part_id = p_part and stage_id = mold.id;
  insert into work_items (project_id, stage_id, part_id, component_no, component_total)
  select pa.project_id, mold.id, p_part, n, p_n from generate_series(1, p_n) n;
  perform audit_action('part.mold_components', 'parts', p_part::text, pa.project_id, coalesce(pa.serial, pa.name) || ': ' || p_n);
end $$;

-- New projects record which stage is which.
create or replace function public.create_panel_project(p jsonb) returns uuid
language plpgsql set search_path = public as $$
declare
  pid uuid;
  tid uuid;
  x jsonb;
  keys jsonb := '{}';
  new_id uuid;
begin
  select id into tid from templates where key = 'exteriorPanels';
  if tid is null then raise exception 'The Exterior panels template is missing.' using errcode = 'P0001'; end if;

  insert into projects (serial, name, template_id, template_label, client, notes, start_date, delivery_date, status, gated)
  values (trim(p ->> 'serial'), coalesce(p ->> 'name', ''), tid, 'Exterior panels', coalesce(p ->> 'client', ''),
          coalesce(p ->> 'notes', ''), (p ->> 'start_date')::date, nullif(p ->> 'delivery_date', '')::date, 'planned', true)
  returning id into pid;

  insert into stages (project_id, name, station_type, station_id, part_hours, sort, step)
  select pid, ts.name, ts.station_type,
         (select w.id from workstations w where w.station_type = ts.station_type order by w.sort, w.name limit 1), 0, ts.sort, ts.step
  from template_stages ts where ts.template_id = tid;

  for x in select * from jsonb_array_elements(coalesce(p -> 'parts', '[]')) order by (value ->> 'parent_key') is not null loop
    insert into parts (project_id, parent_id, serial, name, description, material, finish_colour, finish_sheen, unit_no, sort)
    values (pid, nullif(keys ->> (x ->> 'parent_key'), '')::uuid, x ->> 'serial', trim(x ->> 'name'), coalesce(x ->> 'description', ''),
            x ->> 'material', x ->> 'finish_colour', x ->> 'finish_sheen', nullif(x ->> 'unit_no', '')::int, (x ->> 'sort')::int)
    returning id into new_id;
    keys := keys || jsonb_build_object(x ->> 'key', new_id);
  end loop;

  insert into work_items (project_id, stage_id, part_id)
  select pid, st.id, pa.id from stages st cross join parts pa
  where st.project_id = pid and pa.project_id = pid
    and not exists (select 1 from parts c where c.parent_id = pa.id);

  perform audit_action('project.create', 'projects', pid::text, pid, trim(p ->> 'serial'));
  return pid;
end $$;

-- ════════ migration 20261012000400_modeller_role.sql ════════
-- Amends round 2026-10-12, part 3 (AM-05; Owner's answer: a limited Modeller login). The new role value is
-- added on its own: Postgres can't use a new enum value in the transaction that adds it.
alter type public.app_role add value if not exists 'modeller';

-- ════════ migration 20261012000500_modelling.sql ════════
-- Amends round 2026-10-12, part 3 (AMENDS_NEXT_ROUND AM-05, AM-11; answers in docs/ux/DECISIONS.md):
--   · model data on each part: length × width × height (m), weight (g), surface area (m²), volume (m³) and
--     one render image, entered when its Modelling step is finished; all required before QC;
--   · Modeller login: a member who reads like a Viewer (no costs) and may only start their own Modelling
--     steps, fill in the model data and submit them for QC. Approving stays with Owner and Supervisors.
--   · a login can be linked to its crew person (profiles.person_id), so "own steps" is known.

alter table public.profiles add column person_id uuid unique references public.people (id) on delete set null;

alter table public.parts
  add column length_m   numeric(10,4) check (length_m > 0),
  add column width_m    numeric(10,4) check (width_m > 0),
  add column height_m   numeric(10,4) check (height_m > 0),
  add column weight_g   numeric(12,2) check (weight_g > 0),
  add column surface_m2 numeric(12,4) check (surface_m2 > 0),
  add column volume_m3  numeric(14,6) check (volume_m3 > 0),
  add column render_path text,
  add column model_by   uuid references auth.users (id) on delete set null,
  add column model_at   timestamptz;

-- The signed-in user's crew person, if linked.
create or replace function private.my_person() returns uuid
language sql stable security definer set search_path = '' as $$
  select p.person_id from public.profiles p where p.user_id = auth.uid() and p.active
$$;
grant execute on function private.my_person() to authenticated;

-- Is this the caller's own Modelling step (Modeller login), or is the caller an admin?
create or replace function private.may_model(p_item uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select private.can_write() or (
    private.current_role() = 'modeller' and exists (
      select 1 from public.work_items w join public.stages s on s.id = w.stage_id
      where w.id = p_item and s.step = 'modelling' and w.tech_id is not null and w.tech_id = private.my_person()))
$$;

create or replace function private.model_complete(p_part uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select length_m is not null and width_m is not null and height_m is not null and weight_g is not null
                     and surface_m2 is not null and volume_m3 is not null and coalesce(render_path, '') <> ''
                   from public.parts where id = p_part), false)
$$;

-- Model data for the part of a Modelling step. SECURITY DEFINER with its own check (may_model), because a
-- Modeller can't write parts directly.
create or replace function public.save_model_data(p_item uuid, p jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare part_id uuid;
begin
  if not private.may_model(p_item) then
    raise exception 'Only the modeller on this step, or an admin, can enter its model data.' using errcode = '42501';
  end if;
  select w.part_id into part_id from public.work_items w join public.stages s on s.id = w.stage_id where w.id = p_item and s.step = 'modelling';
  if part_id is null then raise exception 'Model data goes on a Modelling step.' using errcode = 'P0001'; end if;
  -- Only the keys sent change (the render upload sends just render_path).
  update public.parts pa set
    length_m   = case when p ? 'length_m'   then nullif(p ->> 'length_m', '')::numeric   else pa.length_m end,
    width_m    = case when p ? 'width_m'    then nullif(p ->> 'width_m', '')::numeric    else pa.width_m end,
    height_m   = case when p ? 'height_m'   then nullif(p ->> 'height_m', '')::numeric   else pa.height_m end,
    weight_g   = case when p ? 'weight_g'   then nullif(p ->> 'weight_g', '')::numeric   else pa.weight_g end,
    surface_m2 = case when p ? 'surface_m2' then nullif(p ->> 'surface_m2', '')::numeric else pa.surface_m2 end,
    volume_m3  = case when p ? 'volume_m3'  then nullif(p ->> 'volume_m3', '')::numeric  else pa.volume_m3 end,
    render_path = case when p ? 'render_path' then nullif(p ->> 'render_path', '') else pa.render_path end,
    model_by = auth.uid(), model_at = now()
  where pa.id = part_id;
end $$;
revoke all on function public.save_model_data(uuid, jsonb) from public, anon;
grant execute on function public.save_model_data(uuid, jsonb) to authenticated;

-- A Modeller starts their own Modelling step (the gate trigger still applies).
create or replace function public.start_model_step(p_item uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not private.may_model(p_item) then
    raise exception 'Only the modeller on this step, or an admin, can start it.' using errcode = '42501';
  end if;
  update public.work_items set status = 'doing', start_at = coalesce(start_at, now()), seg_start = coalesce(seg_start, now()), end_at = null
  where id = p_item and status in ('todo', 'blocked');
  update public.queue_tasks set status = 'doing', actual_start = coalesce(actual_start, now())
  where work_item_id = p_item and status in ('todo', 'blocked');
end $$;
revoke all on function public.start_model_step(uuid) from public, anon;
grant execute on function public.start_model_step(uuid) to authenticated;

-- Submit for QC: admins for any step; a Modeller for their own Modelling step. A Modelling step needs all its
-- model data first (AM-05).
create or replace function public.submit_qc(p_item uuid) returns void
language plpgsql security definer set search_path = public as $$
declare w work_items; st stages;
begin
  select * into w from work_items where id = p_item for update;
  if not found then raise exception 'That step no longer exists. Reload the page.' using errcode = 'P0001'; end if;
  if not private.can_write() and not private.may_model(p_item) then
    raise exception 'Read-only access. Ask the Owner for Supervisor access to make changes.' using errcode = '42501';
  end if;
  if not (select gated from projects where id = w.project_id) then
    raise exception 'This project has no QC step; mark it Done.' using errcode = 'P0001';
  end if;
  if w.status <> 'doing' then raise exception 'Only a step In Progress can be submitted for QC.' using errcode = 'P0001'; end if;
  if w.tech_id is null then raise exception 'Assign a technician before submitting for QC.' using errcode = 'P0001'; end if;
  if w.qc_since is not null then raise exception 'This step is already waiting for QC.' using errcode = 'P0001'; end if;
  select * into st from stages where id = w.stage_id;
  if st.step = 'modelling' and not private.model_complete(w.part_id) then
    raise exception 'Fill in every model measurement and add the render before submitting for QC.' using errcode = 'P0001';
  end if;
  update work_items set qc_since = now(), qc_by = auth.uid() where id = w.id;
  insert into qc_reviews (project_id, work_item_id, tech_id, attempt, submitted_by)
  values (w.project_id, w.id, w.tech_id, w.attempt, auth.uid());
end $$;
revoke all on function public.submit_qc(uuid) from public, anon;
grant execute on function public.submit_qc(uuid) to authenticated;

-- Renders: a private bucket like the photos. Members read; admins and Modellers upload (the link to a part is
-- set through save_model_data, which checks the step).
do $$
begin
  if exists (select 1 from information_schema.tables where table_schema = 'storage' and table_name = 'buckets') then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('part-renders', 'part-renders', false, 3145728, array['image/jpeg', 'image/png', 'image/webp'])
    on conflict (id) do nothing;
    execute $p$create policy part_renders_read on storage.objects for select to authenticated
      using (bucket_id = 'part-renders' and private.is_member())$p$;
    execute $p$create policy part_renders_insert on storage.objects for insert to authenticated
      with check (bucket_id = 'part-renders' and (private.can_write() or private.current_role() = 'modeller'))$p$;
    execute $p$create policy part_renders_delete on storage.objects for delete to authenticated
      using (bucket_id = 'part-renders' and private.can_write())$p$;
  end if;
end $$;

-- Approving or rejecting stays with Owner and Supervisors (a Modeller's write would otherwise be ignored by RLS
-- without a word).
create or replace function public.decide_qc(p_item uuid, p_approve boolean, p_reason text) returns void
language plpgsql set search_path = public as $$
declare w work_items;
begin
  if not private.can_write() then
    raise exception 'Only the Owner and Supervisors approve or reject in QC.' using errcode = '42501';
  end if;
  select * into w from work_items where id = p_item for update;
  if not found then raise exception 'That step no longer exists. Reload the page.' using errcode = 'P0001'; end if;
  if w.qc_since is null then raise exception 'This step is not waiting for QC.' using errcode = 'P0001'; end if;
  if p_approve then
    update qc_reviews set decided_at = now(), decided_by = auth.uid(), result = 'approved'
    where work_item_id = w.id and result is null;
    perform set_config('app.qc_approve', 'on', true);
    update work_items set status = 'done', end_at = now() where id = w.id;
    perform set_config('app.qc_approve', 'off', true);
    update queue_tasks set status = 'done', actual_end = now() where work_item_id = w.id and status <> 'done';
  else
    if length(trim(coalesce(p_reason, ''))) = 0 then
      raise exception 'Say what failed — it is the only way the rework history is useful.' using errcode = 'P0001';
    end if;
    -- The attempt so far (its QC wait included) closes; the same technician carries on as rework.
    insert into work_segments (work_item_id, project_id, tech_id, start_at, end_at, attempt)
    values (w.id, w.project_id, w.tech_id, coalesce(w.seg_start, w.start_at, now()), now(), w.attempt);
    insert into rework_log (work_item_id, project_id, at, reason, by_user, by_role)
    values (w.id, w.project_id, now(), 'QC: ' || trim(p_reason), auth.uid(), private.current_role());
    update work_items set rework = rework + 1, attempt = attempt + 1, seg_start = now(), qc_since = null, qc_by = null where id = w.id;
    update qc_reviews set decided_at = now(), decided_by = auth.uid(), result = 'rejected', reason = trim(p_reason)
    where work_item_id = w.id and result is null;
  end if;
end $$;


-- ════════ migration 20261013000100_floor_station_role.sql ════════
-- Amends AM-14 (Owner, 2026-10-13): a "Floor Station" login for the shared workshop iPad. The role value is
-- added on its own: Postgres can't use a new enum value in the transaction that adds it.
alter type public.app_role add value if not exists 'floor_station';

-- ════════ migration 20261013000200_requests.sql ════════
-- Amends AM-14 / AM-15 (Owner, 2026-10-13; answers in docs/ux/DECISIONS.md):
--   · the Floor Station (shared workshop iPad) sends two kinds of request about an employee's task:
--     a time extension or a QC check, with an optional note; it can't change anything else;
--   · Owner and Supervisors decide on the Requests page:
--       time extension approved → the extra time is added to the task's allocated time (it doesn't count
--         against the employee); rejected → nothing changes and time beyond the allocation is delay;
--       QC approved → the step passes QC (same as the QC page) or a workshop task is done;
--       QC rejected → the task stays open and the clock keeps running (rework rules of the QC gate);
--   · every request and decision is kept for the performance data.
-- The Floor Station reads like a Viewer (no costs); it writes only through send_request.

create table public.requests (
  id            uuid primary key default gen_random_uuid(),
  kind          text not null check (kind in ('extension', 'qc')),
  queue_task_id uuid references public.queue_tasks (id) on delete set null,
  work_item_id  uuid references public.work_items (id) on delete set null,
  person_id     uuid references public.people (id) on delete set null,
  task_title    text not null default '',
  notes         text not null default '' check (length(notes) <= 1000),
  sent_by       uuid references auth.users (id) on delete set null,
  sent_at       timestamptz not null default now(),
  status        text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  decided_by    uuid references auth.users (id) on delete set null,
  decided_at    timestamptz,
  reply         text not null default '' check (length(reply) <= 1000),
  extra_h       numeric(10,4) check (extra_h > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version    integer not null default 1,
  check ((status = 'pending') = (decided_at is null))
);
create index requests_pending_idx on public.requests (sent_at) where status = 'pending';
select private.standard_triggers('requests');
-- Members read; nobody writes directly: send_request and decide_request below do.
create policy requests_read on public.requests for select to authenticated using (private.is_member());

-- Send a request from the Floor Station (admins may too). Recorded against the task's employee; no PIN.
create or replace function public.send_request(p_queue_task uuid, p_kind text, p_notes text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  t public.queue_tasks;
  w public.work_items;
  rid uuid;
begin
  if not (private.current_role() = 'floor_station' or private.can_write()) then
    raise exception 'Only the Floor Station or an admin can send requests.' using errcode = '42501';
  end if;
  if p_kind not in ('extension', 'qc') then raise exception 'Unknown request type.' using errcode = 'P0001'; end if;
  select * into t from public.queue_tasks where id = p_queue_task;
  if not found then raise exception 'That task no longer exists. Reload the page.' using errcode = 'P0001'; end if;
  if t.status = 'done' then raise exception 'That task is already done.' using errcode = 'P0001'; end if;
  if exists (select 1 from public.requests r where r.queue_task_id = t.id and r.kind = p_kind and r.status = 'pending') then
    raise exception 'A request like this is already waiting for an admin.' using errcode = 'P0001';
  end if;
  if t.work_item_id is not null then select * into w from public.work_items where id = t.work_item_id; end if;

  -- A QC request on a step of a new-workflow project also puts it in the QC list (its clock keeps running).
  if p_kind = 'qc' and w.id is not null and (select p.gated from public.projects p where p.id = w.project_id) then
    if w.status <> 'doing' then raise exception 'Only a task In Progress can be sent for QC.' using errcode = 'P0001'; end if;
    if w.qc_since is null then
      if (select s.step from public.stages s where s.id = w.stage_id) = 'modelling' and not private.model_complete(w.part_id) then
        raise exception 'The model data and render aren''t complete yet; the modeller fills them in on My models first.' using errcode = 'P0001';
      end if;
      update public.work_items set qc_since = now(), qc_by = auth.uid() where id = w.id;
      insert into public.qc_reviews (project_id, work_item_id, tech_id, attempt, submitted_by)
      values (w.project_id, w.id, w.tech_id, w.attempt, auth.uid());
    end if;
  elsif p_kind = 'qc' and t.status <> 'doing' then
    raise exception 'Only a task In Progress can be sent for QC.' using errcode = 'P0001';
  end if;

  insert into public.requests (kind, queue_task_id, work_item_id, person_id, task_title, notes, sent_by)
  values (p_kind, t.id, t.work_item_id, t.person_id, t.title, trim(coalesce(p_notes, '')), auth.uid())
  returning id into rid;
  return rid;
end $$;
revoke all on function public.send_request(uuid, text, text) from public, anon;
grant execute on function public.send_request(uuid, text, text) to authenticated;

-- Decide on a request (Owner and Supervisors).
create or replace function public.decide_request(p_request uuid, p_approve boolean, p_reply text, p_extra_h numeric) returns void
language plpgsql security definer set search_path = '' as $$
declare
  r public.requests;
  t public.queue_tasks;
  gated boolean;
begin
  if not private.can_write() then
    raise exception 'Only the Owner and Supervisors decide on requests.' using errcode = '42501';
  end if;
  select * into r from public.requests where id = p_request for update;
  if not found then raise exception 'That request no longer exists. Reload the page.' using errcode = 'P0001'; end if;
  if r.status <> 'pending' then raise exception 'Someone has already decided on this request.' using errcode = 'P0001'; end if;
  if r.queue_task_id is not null then select * into t from public.queue_tasks where id = r.queue_task_id; end if;
  select coalesce(p.gated, false) into gated from public.work_items w join public.projects p on p.id = w.project_id where w.id = r.work_item_id;

  if r.kind = 'extension' and p_approve then
    if p_extra_h is null or p_extra_h <= 0 or p_extra_h > 200 then
      raise exception 'Enter the extra time to add, more than 0.' using errcode = 'P0001';
    end if;
    if t.id is not null then
      -- Allocated time in hours (a task planned in days becomes hours; one working day is the day's hours).
      update public.queue_tasks set dur_value = (case when dur_unit = 'days'
          then dur_value * coalesce((select (extract(epoch from ((value ->> 'shiftEnd')::time - (value ->> 'shiftStart')::time)) / 3600)
                                             - coalesce((value ->> 'breakMins')::numeric, 0) / 60 from public.settings where key = 'calendar'), 8)
          else dur_value end) + p_extra_h,
        dur_unit = 'hours'
      where id = t.id;
    end if;
    if r.work_item_id is not null and gated then
      update public.work_items set plan_h = coalesce(plan_h, 0) + p_extra_h where id = r.work_item_id;
    end if;
  elsif r.kind = 'qc' and r.work_item_id is not null and gated then
    -- Same as deciding on the QC page (the step was put in the QC list when the request was sent).
    if exists (select 1 from public.work_items w where w.id = r.work_item_id and w.qc_since is not null) then
      perform public.decide_qc(r.work_item_id, p_approve, case when p_approve then '' else coalesce(nullif(trim(p_reply), ''), 'QC not approved') end);
    end if;
  elsif r.kind = 'qc' and p_approve and t.id is not null then
    -- A workshop task (or an old-project step): approved QC finishes it.
    update public.queue_tasks set status = 'done', actual_end = now() where id = t.id and status <> 'done';
  end if;

  update public.requests set status = case when p_approve then 'approved' else 'rejected' end,
    decided_by = auth.uid(), decided_at = now(), reply = trim(coalesce(p_reply, '')),
    extra_h = case when r.kind = 'extension' and p_approve then p_extra_h end
  where id = r.id;
end $$;
revoke all on function public.decide_request(uuid, boolean, text, numeric) from public, anon;
grant execute on function public.decide_request(uuid, boolean, text, numeric) to authenticated;

-- ════════ migration 20261014000100_model_qc_requests.sql ════════
-- My models (Owner, 2026-10-14; docs/ux/DECISIONS.md):
--   · a Modeller's "Ask for QC" also shows on Requests (badge and chime), like a Floor Station QC request;
--   · deciding a step on the QC page closes its pending QC request, and deciding the request decides the step
--     (decide_request already calls decide_qc), so the two lists never disagree.

-- Close the pending QC requests of a step (SECURITY DEFINER: nobody writes requests directly).
create or replace function private.close_qc_requests(p_item uuid, p_approve boolean, p_reply text) returns void
language sql security definer set search_path = '' as $$
  update public.requests set status = case when p_approve then 'approved' else 'rejected' end,
    decided_by = auth.uid(), decided_at = now(), reply = trim(coalesce(p_reply, ''))
  where work_item_id = p_item and kind = 'qc' and status = 'pending';
$$;
revoke all on function private.close_qc_requests(uuid, boolean, text) from public, anon;
grant execute on function private.close_qc_requests(uuid, boolean, text) to authenticated;

create or replace function public.submit_qc(p_item uuid) returns void
language plpgsql security definer set search_path = public as $$
declare w work_items; st stages; pa parts;
begin
  select * into w from work_items where id = p_item for update;
