  end if;
  select * into w from work_items where id = p_item for update;
  if not found then raise exception 'That step no longer exists. Reload the page.' using errcode = 'P0001'; end if;
  if not (select gated from projects where id = w.project_id) then
    raise exception 'This project has no QC step; mark it Done.' using errcode = 'P0001';
  end if;
  if w.qc_since is null and w.status <> 'doing' then
    raise exception 'Only a step In Progress can pass or fail QC. Set it In Progress first.' using errcode = 'P0001';
  end if;
  select * into st from stages where id = w.stage_id;
  if p_pass and st.step = 'modelling' and not private.model_complete(w.part_id) then
    raise exception 'No model record yet: the measurements and render must be saved on My models first.' using errcode = 'P0001';
  end if;
  if p_pass and st.step = 'printing' and not private.print_complete(w.part_id) then
    raise exception 'No print record yet: the filament, printing time and slice components must be saved on 3D Printing first.' using errcode = 'P0001';
  end if;
  if not p_pass and length(trim(coalesce(p_reason, ''))) = 0 then
    raise exception 'Say what failed — it is the only way the rework history is useful.' using errcode = 'P0001';
  end if;
  if w.qc_since is null then
    if w.tech_id is null then raise exception 'Assign a technician before deciding QC.' using errcode = 'P0001'; end if;
    update work_items set qc_since = now(), qc_by = auth.uid() where id = w.id;
    insert into qc_reviews (project_id, work_item_id, tech_id, attempt, submitted_by)
    values (w.project_id, w.id, w.tech_id, w.attempt, auth.uid());
  end if;
  perform decide_qc(w.id, p_pass, coalesce(p_reason, ''));
end $$;
revoke all on function public.board_qc(uuid, boolean, text) from public, anon;
grant execute on function public.board_qc(uuid, boolean, text) to authenticated;

-- ════════ migration 20261015000300_crew_archive.sql ════════
-- Amends round 3 (Owner, 2026-10-14; docs/ux/DECISIONS.md), AM-20:
--   · each employee is Active or Inactive (the existing `active` switch); Inactive people are hidden from the TV,
--     the Floor Station and task assignment but stay in Crew;
--   · Delete erases nothing: the person moves to "Deleted accounts" (archived_at) with all their history, and can
--     be restored;
--   · before someone is set Inactive or deleted, their open tasks are moved to another person or left unassigned;
--   · salaries: the Owner and Supervisors view and change them (people_cost); every other role still can't.
--     Hour rates, labour costs and the cost settings stay Owner-only.

alter table public.people add column archived_at timestamptz;
alter table public.people add constraint people_archived_inactive check (archived_at is null or not active);

drop policy if exists people_cost_owner on public.people_cost;
create policy people_cost_admin on public.people_cost for all to authenticated
  using (private.can_write()) with check (private.can_write());

-- Set a person Inactive, delete (archive) them, or restore / reactivate them. Open work (part steps not done,
-- queue tasks not done) moves to p_move_to; without one, part steps are left unassigned and queue tasks stay on
-- the person's (hidden) queue. Owner and Supervisors only (RLS on people, work_items and queue_tasks).
create or replace function public.set_person_status(p_person uuid, p_status text, p_move_to uuid default null) returns jsonb
language plpgsql set search_path = public as $$
declare
  pe people;
  moved_steps int := 0;
  moved_tasks int := 0;
begin
  if not private.can_write() then
    raise exception 'Only the Owner and Supervisors change a crew member''s status.' using errcode = '42501';
  end if;
  if p_status not in ('active', 'inactive', 'deleted', 'restored') then raise exception 'Unknown status.' using errcode = 'P0001'; end if;
  select * into pe from people where id = p_person for update;
  if not found then raise exception 'That person no longer exists. Reload the page.' using errcode = 'P0001'; end if;
  if p_move_to is not null then
    if p_move_to = p_person then raise exception 'Pick someone else to take the open tasks.' using errcode = 'P0001'; end if;
    if not exists (select 1 from people where id = p_move_to and active and archived_at is null) then
      raise exception 'Open tasks can only move to an active crew member.' using errcode = 'P0001';
    end if;
  end if;

  if p_status in ('inactive', 'deleted') then
    update work_items set tech_id = p_move_to where tech_id = p_person and status <> 'done';
    get diagnostics moved_steps = row_count;
    if p_move_to is not null then
      update queue_tasks set person_id = p_move_to where person_id = p_person and status <> 'done';
      get diagnostics moved_tasks = row_count;
    end if;
    update people set active = false, archived_at = case when p_status = 'deleted' then now() else archived_at end where id = p_person;
  elsif p_status = 'restored' then
    update people set archived_at = null where id = p_person;
  else
    update people set active = true, archived_at = null where id = p_person;
  end if;

  perform audit_action('crew_' || p_status, 'people', p_person::text, null,
    pe.name || ' · ' || case p_status when 'active' then 'set active' when 'inactive' then 'set inactive'
      when 'deleted' then 'moved to Deleted accounts' else 'restored from Deleted accounts' end,
    jsonb_build_object('moved_to', p_move_to, 'part_steps', moved_steps, 'queue_tasks', moved_tasks));
  return jsonb_build_object('part_steps', moved_steps, 'queue_tasks', moved_tasks);
end $$;
revoke all on function public.set_person_status(uuid, text, uuid) from public, anon;
grant execute on function public.set_person_status(uuid, text, uuid) to authenticated;

-- ════════ migration 20261015000400_admin_corrections.sql ════════
-- Owner, 2026-10-15 (docs/ux/DECISIONS.md): Owner and Supervisors can correct model and print data on any step,
-- also while it waits for QC and after it is approved. A Modelling & 3D Printing user can't change a step once it
-- is sent to QC or approved (the app already locked it; now the database does too). A step waiting for QC or
-- approved never loses a value: every field (and the render) must stay filled.

create or replace function public.save_model_data(p_item uuid, p jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare w public.work_items;
begin
  if not private.may_model(p_item) then
    raise exception 'Only the modeller on this step, or an admin, can enter its model data.' using errcode = '42501';
  end if;
  select wi.* into w from public.work_items wi join public.stages s on s.id = wi.stage_id where wi.id = p_item and s.step = 'modelling';
  if w.id is null then raise exception 'Model data goes on a Modelling step.' using errcode = 'P0001'; end if;
  if (w.qc_since is not null or w.status = 'done') and not private.can_write() then
    raise exception 'This model is with QC or approved; only the Owner or a Supervisor can change it now.' using errcode = '42501';
  end if;
  -- Only the keys sent change (the render upload sends just render_path).
  update public.parts pa set
    length_m   = case when p ? 'length_m'   then nullif(p ->> 'length_m', '')::numeric   else pa.length_m end,
    width_m    = case when p ? 'width_m'    then nullif(p ->> 'width_m', '')::numeric    else pa.width_m end,
    height_m   = case when p ? 'height_m'   then nullif(p ->> 'height_m', '')::numeric   else pa.height_m end,
    weight_g   = case when p ? 'weight_g'   then nullif(p ->> 'weight_g', '')::numeric   else pa.weight_g end,
    surface_m2 = case when p ? 'surface_m2' then nullif(p ->> 'surface_m2', '')::numeric else pa.surface_m2 end,
    volume_m3  = case when p ? 'volume_m3'  then nullif(p ->> 'volume_m3', '')::numeric  else pa.volume_m3 end,
    render_path = case when p ? 'render_path' then nullif(p ->> 'render_path', '') else pa.render_path end,
    model_by = auth.uid(), model_at = now()
  where pa.id = w.part_id;
  if (w.qc_since is not null or w.status = 'done') and not private.model_complete(w.part_id) then
    raise exception 'A model with QC or approved keeps every measurement and its render.' using errcode = 'P0001';
  end if;
end $$;

create or replace function public.save_print_data(p_item uuid, p jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare w public.work_items;
begin
  if not private.may_print(p_item) then
    raise exception 'Only the person on this print job, or an admin, can enter its print data.' using errcode = '42501';
  end if;
  select wi.* into w from public.work_items wi join public.stages s on s.id = wi.stage_id where wi.id = p_item and s.step = 'printing';
  if w.id is null then raise exception 'Print data goes on a 3D printing step.' using errcode = 'P0001'; end if;
  if (w.qc_since is not null or w.status = 'done') and not private.can_write() then
    raise exception 'This print job is with QC or approved; only the Owner or a Supervisor can change it now.' using errcode = '42501';
  end if;
  update public.parts pa set
    print_filament_g = case when p ? 'print_filament_g' then nullif(p ->> 'print_filament_g', '')::numeric else pa.print_filament_g end,
    print_min        = case when p ? 'print_min'        then nullif(p ->> 'print_min', '')::numeric        else pa.print_min end,
    print_slices     = case when p ? 'print_slices'     then nullif(p ->> 'print_slices', '')::int         else pa.print_slices end,
    print_by = auth.uid(), print_at = now()
  where pa.id = w.part_id;
  if (w.qc_since is not null or w.status = 'done') and not private.print_complete(w.part_id) then
    raise exception 'A print job with QC or approved keeps its filament, printing time and slice components.' using errcode = 'P0001';
  end if;
end $$;

-- ════════ migration 20261015000500_preview_request.sql ════════
-- Owner, 2026-10-15 (docs/ux/DECISIONS.md): "Preview as Modelling & 3D Printing". The Owner tests the role's
-- pages from their own login; a Submit for QC sent from the preview also shows on Requests, as a Modelling &
-- 3D Printing user's would (submit_qc only adds the request for non-admins). Sent by the Owner's login.
create or replace function public.preview_qc_request(p_item uuid, p_notes text default '') returns void
language plpgsql security definer set search_path = public as $$
declare w work_items; st stages; pa parts;
begin
  if private.current_role() is distinct from 'owner' then
    raise exception 'Only the Owner can use the preview.' using errcode = '42501';
  end if;
  select * into w from work_items where id = p_item;
  if not found or w.qc_since is null then return; end if;
  if exists (select 1 from requests r where r.work_item_id = w.id and r.kind = 'qc' and r.status = 'pending') then return; end if;
  select * into st from stages where id = w.stage_id;
  select * into pa from parts where id = w.part_id;
  insert into requests (kind, queue_task_id, work_item_id, person_id, task_title, notes, sent_by)
  values ('qc', (select q.id from queue_tasks q where q.work_item_id = w.id order by q.created_at limit 1), w.id, w.tech_id,
          trim(coalesce(pa.serial, '') || ' ' || coalesce(pa.name, '')) || ': ' || st.name, trim(coalesce(p_notes, '')), auth.uid());
end $$;
revoke all on function public.preview_qc_request(uuid, text) from public, anon;
grant execute on function public.preview_qc_request(uuid, text) to authenticated;

-- ════════ migration 20261016000100_absences.sql ════════
-- Amends round 4 (Owner, 2026-10-16; docs/ux/DECISIONS.md), AM-29: Floor log attendance.
--   · Everyone is present by default; an admin marks someone absent for a number of working days with a leave
--     type (sick, annual, unpaid / other, unexcused) and an optional note.
--   · Before saving, each of their pending tasks is reassigned or kept; the first kept task is pinned to start at
--     shift start on the day they return (the app works out the dates on the shop calendar).
--   · No hours can be logged for someone on a day they are marked absent (cancel or shorten the absence first).
--   · Absences can be edited or cancelled; every change is in the audit log (generic trigger).

create type public.leave_type as enum ('sick', 'annual', 'unpaid', 'unexcused');

create table public.absences (
  id           uuid primary key default gen_random_uuid(),
  person_id    uuid not null references public.people (id) on delete cascade,
  kind         public.leave_type not null,
  starts_on    date not null,
  days         integer not null check (days between 1 and 365),
  -- Last absent working day and the day they are back, from the shop calendar (rest days and holidays skipped).
  ends_on      date not null,
  back_on      date not null,
  note         text not null default '' check (length(note) <= 1000),
  cancelled_at timestamptz,
  created_by   uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  version      integer not null default 1,
  check (ends_on >= starts_on and back_on > ends_on)
);
create index absences_person_idx on public.absences (person_id, starts_on);
alter table public.absences enable row level security;
select private.standard_triggers('absences');
select private.member_policies('absences');

-- Someone marked absent on a day can't have hours logged that day.
create or replace function private.no_hours_when_absent() returns trigger
language plpgsql security definer set search_path = '' as $$
declare a public.absences; who text;
begin
  select * into a from public.absences
  where person_id = new.person_id and cancelled_at is null and new.day between starts_on and ends_on limit 1;
  if found then
    select name into who from public.people where id = new.person_id;
    raise exception '% is marked absent on %. Cancel or shorten the absence before logging hours.', who, to_char(new.day, 'DD Mon')
      using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger hour_logs_absent before insert or update on public.hour_logs
  for each row execute function private.no_hours_when_absent();

-- Mark someone absent, with the decision on each pending task, in one go. SECURITY INVOKER: RLS applies.
--   p_reassign: [{ "task": queue task id, "to": person id }]; their linked part steps move too.
--   p_push_task / p_push_at: the first kept task, pinned to start when they are back.
create or replace function public.mark_absent(p_person uuid, p_kind public.leave_type, p_starts date, p_days integer,
  p_ends date, p_back date, p_note text, p_reassign jsonb, p_push_task uuid, p_push_at timestamptz) returns uuid
language plpgsql set search_path = public as $$
declare r jsonb; t queue_tasks; new_id uuid;
begin
  if not private.can_write() then
    raise exception 'Only the Owner and Supervisors mark someone absent.' using errcode = '42501';
  end if;
  if exists (select 1 from absences where person_id = p_person and cancelled_at is null
             and daterange(starts_on, ends_on, '[]') && daterange(p_starts, p_ends, '[]')) then
    raise exception 'This person already has an absence in those days. Edit that one instead.' using errcode = 'P0001';
  end if;
  insert into absences (person_id, kind, starts_on, days, ends_on, back_on, note, created_by)
  values (p_person, p_kind, p_starts, p_days, p_ends, p_back, trim(coalesce(p_note, '')), auth.uid())
  returning id into new_id;

  for r in select * from jsonb_array_elements(coalesce(p_reassign, '[]')) loop
    select * into t from queue_tasks where id = (r ->> 'task')::uuid and person_id = p_person and status <> 'done';
    continue when not found;
    if (r ->> 'to')::uuid = p_person then continue; end if;
    update queue_tasks set person_id = (r ->> 'to')::uuid, fixed_start = null where id = t.id;
    if t.work_item_id is not null then
      update work_items set tech_id = (r ->> 'to')::uuid where id = t.work_item_id and status <> 'done';
    end if;
  end loop;

  if p_push_task is not null then
    update queue_tasks set fixed_start = p_push_at where id = p_push_task and person_id = p_person and status <> 'done';
  end if;

  perform audit_action('absence', 'absences', new_id::text, null,
    (select name from people where id = p_person) || ' · ' || p_kind::text || ' from ' || to_char(p_starts, 'DD Mon') || ', ' || p_days || ' working day(s), back ' || to_char(p_back, 'DD Mon'),
    jsonb_build_object('reassigned', jsonb_array_length(coalesce(p_reassign, '[]')), 'pushed', p_push_task is not null));
  return new_id;
end $$;
revoke all on function public.mark_absent(uuid, public.leave_type, date, integer, date, date, text, jsonb, uuid, timestamptz) from public, anon;
grant execute on function public.mark_absent(uuid, public.leave_type, date, integer, date, date, text, jsonb, uuid, timestamptz) to authenticated;

-- ════════ migration 20261017000100_theme.sql ════════
-- Theme switch (Joey, 2026-10-17; docs/amends/THEME_SWITCH_PROMPT.md): each person's Light / Dark / System choice,
-- kept on their profile so it follows them across devices (the browser keeps a copy so pages open in the right
-- theme without a flash). Dark, the Kynetik look, is the default.
--   · Only the person themself changes it, through set_theme (profiles are otherwise Owner-only to update).
--   · A theme change is a display preference, not tracker data: it is left out of the audit log.

alter table public.profiles
  add column theme text not null default 'dark' check (theme in ('light', 'dark', 'system'));

create or replace function public.set_theme(p_theme text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_theme is null or p_theme not in ('light', 'dark', 'system') then
    raise exception 'Choose Light, Dark or System.';
  end if;
  perform set_config('app.skip_audit', 'on', true);
  update public.profiles set theme = p_theme where user_id = auth.uid();
  perform set_config('app.skip_audit', 'off', true);
end $$;

revoke all on function public.set_theme(text) from public;
grant execute on function public.set_theme(text) to authenticated;

